import re
fname='ric3proj/cill/cti.vcd'
ids={'launch':'@','dbg':'E','cpu_state':'!!'}
# But cpu_state id maybe '!!'? Actually from snippet line 551: b01000000 !! corresponds to cpu_state maybe.
# We'll parse variable definitions to map names to ids for safety.
name_to_id={}
with open(fname) as f:
    for line in f:
        if line.startswith('$var'):
            parts=line.split()
            # $var <type> <width> <id> <ref> $end
            if len(parts)>=5:
                vid=parts[3]
                ref=parts[4]
                # handle hierarchical? later scopes not included
                name_to_id[ref]=vid
        if line.startswith('$enddefinitions'):
            break
print('id launch_next_insn',name_to_id.get('launch_next_insn'))
print('id dbg_next',name_to_id.get('dbg_next'))
print('id cpu_state',name_to_id.get('cpu_state'))

id_launch=name_to_id['launch_next_insn']
id_dbg=name_to_id['dbg_next']
id_state=name_to_id['cpu_state']

cur_time=None
vals={id_launch:None,id_dbg:None,id_state:None}
# VCD values persist until changed.
# We'll collect at each timestamp.
records=[]
with open(fname) as f:
    for line in f:
        line=line.strip()
        if not line:
            continue
        if line.startswith('#'):
            if cur_time is not None:
                records.append((cur_time,vals[id_launch],vals[id_dbg],vals[id_state]))
            cur_time=int(line[1:])
        elif line.startswith('b'):
            m=re.match(r'b([01xXzZ]+)\s+(\S+)$',line)
            if m:
                bits,vid=m.group(1),m.group(2)
                if vid in vals:
                    vals[vid]=bits
        else:
            # scalar form like 0!, 1E etc
            m=re.match(r'([01xXzZ])(\S+)$',line)
            if m:
                v,vid=m.group(1),m.group(2)
                if vid in vals:
                    vals[vid]=v
    # last timestamp
    if cur_time is not None:
        records.append((cur_time,vals[id_launch],vals[id_dbg],vals[id_state]))

for t,l,d,s in records:
    print(t,l,d,s)
