		if (reset) begin
			h_launch_next_q <= 0;
			h_dbg_insn_opcode_q <= 0;
			h_next_pc_q <= 0;
			h_pipe_ready <= 0;
		end else begin
			h_launch_next_q <= wrapper.uut.launch_next_insn;
			h_dbg_insn_opcode_q <= wrapper.uut.dbg_insn_opcode;
			h_next_pc_q <= wrapper.uut.next_pc;
			h_pipe_ready <= 1;
		end
