		if (!reset && h_pipe_ready) begin
			h_dbg_next_tracks_launch: assert(wrapper.uut.dbg_next == h_launch_next_q);
			h_q_insn_tracks_dbg: assert(wrapper.uut.q_insn_opcode == h_dbg_insn_opcode_q);
			if (h_launch_next_q) begin
